  "explanation": "The retrieval showed that a related hypothesis on connector portability received preliminary support but with marginal power (n=92) and was treated as exploratory. Multiple related tests failed due to small samples (n=19, 44). The current sample of n=24 shapers is even smaller, making a well-powered test extremely unlikely. Without this evidence, one might have underestimated the sample-size barrier."
 },
 "testability": {
  "p_testable": 0.15,
  "blocking_constraints": [
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "n=24 shaper movers is too small to detect the modest effect sizes seen in prior connector work (CHT-057 MDE would be >0.3 in correlation scale)."
   },
   {
    "code": "EXPOSURE_SPARSITY",
    "text": "Few shapers may have highly skewed cut/drive shares, so the contrast between cut-heavy and drive-heavy subgroups may be extremely small."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": ["FAM:SF-CHT-057"],
  "summary": "CHT-057 found that pre-move cut share predicted connector portability (n=92), but this covered all connectors, not specifically shapers. The finding was exploratory and treated as a boundary condition, not a confirmatory test. The current question narrows the population to shapers, leaving the specific hypothesis unconfirmed."
 },
 "risks": [
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "The sample of 24 shaper movers severely limits power; prior work with 92 connectors found only a moderate effect and flagged small-sample risk."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Dichotomising shapers into cut-heavy and drive-heavy may produce very small, imbalanced subgroups."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "Play-type initiation assignment for low-usage players may be noisy, attenuating true differences."
  },
  {
   "code": "CONFOUNDING",
   "text": "Destination team system, roster fit, and changing player roles could confound portability differences independent of cut vs drive style."
  },
  {
   "code": "MULTIPLE_TESTING",
   "text": "If multiple operationalisations of cut-heavy and portability are explored, false discovery risk increases."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.10,
  "untestable": 0.70,
  "artifact": 0.05,
  "uncertain": 0.10
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Difference in post-move role portability (e.g., reproduction of structural influence or play-type mix change) between shapers whose pre-move initiation diet is cut-heavy versus drive-heavy.",
  "unit": "One shaper's inter-team move (player-season pair across seasons).",
  "sample": "All players classified as Shapers (low usage, positive residual influence) who changed teams between 2022-23 and 2025-26, yielding an estimated n=24.",
  "power": "Power analysis not possible with confidence; based on CHT-057, expected effect size rho ~0.25, requiring n > 100 for 80% power. With n=24, MDE > 0.5, making the test severely underpowered.",
  "controls": "Destination team play-style, change in usage, landing-spot strength, age, and injury history. With n=24, at most 1-2 covariates could be included without overfitting.",
  "falsification": "Permutation test shuffling cut/drive labels; check that the result is not driven by a single outlier (e.g., drop highest-leverage mover); test whether pre-move drive share also predicts portability in a neutral direction.",
  "multiplicity": "Pre-register a single primary contrast (e.g., continuous cut share vs. portability outcome) and a single secondary (cut-heavy vs drive-heavy tercile split) with Bonferroni correction.",
  "decision_rule": "Two-sided alpha=0.05 on the primary Spearman correlation between pre-move cut share and Delta (1 - cosine similarity of pre- and post-move initiation mixes).",
  "data_version": "NBA 2022-23 through 2025-26 regular seasons, per-game play-by-play and derived possession records as of 2026-08-08."
 }
}}

